        StoryItem(id: "comet", kind: .massage, kindLabel: "Massage story", title: "Lumi and the Sleepy Comet", color: 0x7E63B8, chips: ["Sleep", "Dry skin", "Research-based strokes"],
                  summary: "A full bedtime story. Lumi the Star Catcher follows a sleepy comet across {child}'s back, arms, hands and legs, and every part of the story is a different massage stroke. Soft music plays underneath.", age: "1+", length: "10 or 20 min", benefits: ["Strokes follow the moderate-pressure massage used in eczema and infant sleep studies", "A real bedtime story, told while you massage", "Gentle on flares: no massage on flaring skin"], factKey: "protocol",
                  steps: [
                    MassageStep("Ask first", cue: "Rest both palms still on their back, then ask", story: "Once upon a time, high above the sleepy rooftops, there lived a star catcher named Lumi. Before every adventure, Lumi always asks first. Grown-up, rest your hands gently and ask: can I put on your magic cream? Wait for a yes.", zones: ["upper"], motion: "still", view: "back", reps: "Wait for a yes", seconds: 40, isOptional: false),
                    MassageStep("Warm the cream", cue: "Rub a generous amount between your palms", story: "Lumi opened her little jar of moonlight cream and warmed it between her hands, slowly, until it felt cozy.", zones: ["lower"], motion: "open", view: "back", reps: "10 seconds", seconds: 15, isOptional: false),
                    MassageStep("Spread the cream", cue: "Flat palms sweep the cream across the whole back", story: "She spread the night across the sky, like smoothing a soft blanket. The sky grew dark and quiet, and the first stars blinked awake.", zones: ["upper"], motion: "open", view: "back", reps: "×3 slow", seconds: 60, isOptional: false),
                    MassageStep("Long strokes", cue: "Hand over hand, neck to hips. Moderate pressure, firm enough not to tickle.", story: "Then Lumi saw a sleepy comet sliding slowly down the sky. Whoosh. And another whoosh. One hand follows the other, all the way down.", zones: ["upper"], motion: "glide", view: "back", reps: "×8 slow", seconds: 120, isOptional: false),
