                    MassageStep("Open the hands", cue: "Gently open their fingers, then glide both thumbs from the palm out to the fingers", story: "At the end of the slides, Lumi found two little hands holding on tight. She opened them gently and smoothed starlight across each palm.", zones: ["palm"], motion: "palmOpen", view: "palm", reps: "Each hand ×4", seconds: 80, isOptional: false),
                    MassageStep("Left leg", cue: "Long strokes from hip to ankle, with a gentle squeeze", story: "Two long rivers of starlight flowed down to the sea. Lumi followed the first river all the way down.", zones: ["legL"], motion: "glide", view: "front", reps: "×5", seconds: 70, isOptional: false),
                    MassageStep("Right leg", cue: "Same on the other leg", story: "And down the second river, all the way to the toes. The rivers grew still and smooth.", zones: ["legR"], motion: "glide", view: "front", reps: "×5", seconds: 70, isOptional: true),
                    MassageStep("Feet", cue: "Thumbs glide from heel to toes on each foot", story: "At the end of the rivers, ten little toe stars were waiting. Lumi smoothed a moon path from heel to toes.", zones: ["sole"], motion: "footGlide", view: "foot", reps: "Each foot ×4", seconds: 70, isOptional: true),
                    MassageStep("Open the chest", cue: "Flat hands start at the middle of the chest and glide outward", story: "The whole sky took a big, slow breath. In, and the sky opened wide like a book. Out, and it settled down soft.", zones: ["chestL", "chestR"], motion: "open", view: "front", reps: "With 4 slow breaths", seconds: 60, isOptional: false),
