        StoryItem(id: "flareStory", kind: .massage, kindLabel: "Massage story", title: "Lumi's Gentle Night", color: 0x5A6FB8, chips: ["Flare nights", "Extra gentle"],
                  summary: "For flare nights: slow, feather-light strokes on calm skin only, and gentle smoothing on flaring spots. About 6 minutes.", age: "1+", length: "6 min", benefits: ["No massage on flaring skin", "Cream still goes on, gently", "Calming even on hard nights"], factKey: "eczema",
