        StoryItem(id: "parentCalm", kind: .calm, kindLabel: "For parents", title: "Two Minutes for You", color: 0xB9637A, chips: ["Parents", "Calm"],
                  summary: "A short reset for the grown-up. Hard nights are hard on you too.", age: "Parents", length: "2 min", benefits: ["A moment to breathe", "Calmer hands, calmer child", "You are doing a good job"], factKey: "parent",
                  steps: [],
                  chapters: [], ending: "", lines: ["Drop your shoulders. Unclench your jaw.", "Breathe in for four. Out for six.", "Tonight does not have to be perfect.", "You showed up. That matters more than anything."]),
        StoryItem(id: "sleepy", kind: .bedtimeStory, kindLabel: "Bedtime story", title: "Sleepy Otter and the Cool River", color: 0x3F8FB0, chips: ["Audio only", "Choose the length"],
                  summary: "Pip the otter feels hot and prickly after a long sunny day, until Mama shows her the cool, moonlit river.", age: "2+", length: "5–20 min", benefits: ["Cool, calming imagery for itchy nights", "Slows breathing before sleep", "Audio only, screen stays dark"], factKey: "sleep",
                  steps: [],
                  chapters: [StoryChapter(title: "The Warm Day", text: "Pip the otter had played in the sunshine all day long. She had splashed and tumbled and chased dragonflies until the sky turned orange. Now her fur felt warm and prickly, like a sweater that was much too thick. \"Mama,\" she said, wriggling, \"I wish I could feel cool.\" Mama Otter smiled a slow, sleepy smile. \"I know just the place,\" she whispered. \"Come with me.\""), StoryChapter(title: "The Moonlit River", text: "They padded down the soft, mossy path to the river. The moon was rising, and it poured silver light across the water. Pip dipped in one paw. Cool. Then another paw. Cool, cool. Then her whole self slid in, slow and smooth. The prickly feeling began to float away, like a leaf drifting downstream."), StoryChapter(title: "Floating on Your Back", text: "\"Watch me,\" said Mama. She rolled onto her back and floated, paws resting on her tummy. Pip tried too. At first she wobbled. Then she let her body go heavy and loose, and the river held her up. Above her, the stars came out one by one. Pip counted them. One. Two. Three. Four. Five. And then she forgot to count, and just breathed."), StoryChapter(title: "The Heron's Song", text: "On the riverbank, an old grey heron stood on one leg among the reeds. He began to hum, low and slow, a song as old as the river. The reeds swayed with it. The water rippled with it. Pip's breathing slowed to match it. In, like the river flowing. Out, like the wind in the reeds. In. And out.")], ending: "Mama scooped Pip up and carried her home to their nest of cool, soft moss. \"Goodnight, river,\" Pip whispered. \"Goodnight, stars. Goodnight, heron.\" Her eyes grew heavy, heavier, heavier still. And now it is your turn. Let your body feel heavy, like Pip floating on the river. Your skin is cool. Your breath is slow. You are safe, and you are loved. Goodnight.", lines: []),
        StoryItem(id: "littleStar", kind: .bedtimeStory, kindLabel: "Bedtime story", title: "Lumi and the Littlest Star", color: 0x4F6FB8, chips: ["Audio only", "Choose the length"],
                  summary: "Lumi the Star Catcher finds a tiny star hiding behind a cloud, too wiggly and itchy to shine. A story about belonging, just as you are.", age: "3+", length: "5–20 min", benefits: ["Gentle message: you belong as you are", "Familiar Lumi character from the massage stories", "Audio only, screen stays dark"], factKey: "quality",
                  steps: [],
                  chapters: [StoryChapter(title: "A Star Too Small", text: "Every night, Lumi the Star Catcher climbed her long silver ladder to polish the stars. She polished the big ones and the bright ones and the ones that twinkled blue. But tonight, behind a soft grey cloud, she spotted a tiny star, glowing very, very dimly. \"Hello, little one,\" Lumi said. \"Why are you hiding?\""), StoryChapter(title: "Why So Dim?", text: "\"I am not bright like the others,\" the littlest star whispered. \"Some nights I feel itchy and wiggly, and I just can't shine.\" Lumi sat down on the edge of the cloud. \"Do you know a secret?\" she said. \"Even the brightest stars have wiggly nights. Every single one.\" The little star peeked out, just a bit."), StoryChapter(title: "The Moonlight Cream", text: "Lumi opened her pocket and took out a small jar of moonlight cream. \"May I?\" she asked. The little star nodded. Lumi smoothed the cream on in slow, gentle circles. Round and round. Slow and soft. The little star giggled, then sighed, and its glow grew a little warmer, a little brighter."), StoryChapter(title: "A Place in the Sky", text: "\"Now,\" said Lumi, \"let's find your place.\" They floated past the big bright stars, who all scooted over to make room. Right beside the moon there was a perfect little space, just the right size. The littlest star settled in. And together, all the stars made a shape in the sky. It looked like a heart.")], ending: "\"You don't have to be the brightest to belong,\" Lumi whispered. \"You just have to be you.\" The littlest star twinkled softly. Slower. And slower. And then it fell fast asleep. Close your eyes now. Somewhere inside you, your own little star is glowing, soft and warm. You belong, just as you are. Goodnight.", lines: []),
        StoryItem(id: "whale", kind: .bedtimeStory, kindLabel: "Bedtime story", title: "Wren the Whale's Lullaby", color: 0x2F6F9A, chips: ["Audio only", "Choose the length"],
                  summary: "Deep in the cool blue sea, a gentle whale helps a wiggly little fish learn to rest, by breathing slow like the tide.", age: "2+", length: "5–20 min", benefits: ["Teaches slow breathing through story", "Deep, cool, ocean imagery", "Audio only, screen stays dark"], factKey: "relax",
                  steps: [],
                  chapters: [StoryChapter(title: "The Deep Blue", text: "Far out in the ocean, where the water is cool and deep and blue, lived a whale named Wren. Everything around Wren moved slowly. The seaweed swayed slowly. The jellyfish drifted slowly. And Wren swam slowest of all, gliding through the quiet water like a great, gentle cloud."), StoryChapter(title: "A Fish Who Couldn't Sleep", text: "One night, a tiny fish named Finn zipped up to Wren. Zip, zip, zip. \"I can't sleep,\" said Finn. \"My fins are wiggly and my tummy is fluttery and I just keep swimming.\" Wren blinked a big, slow blink. \"I know how that feels,\" she said. \"Would you like to rest with me?\""), StoryChapter(title: "Slow Like the Tide", text: "\"Watch,\" said Wren. She rose up toward the moonlight and took a long, deep breath in. Then she sank down, down, down, and let it out slowly. Finn tried it. Rise up, breathe in. Sink down, breathe out. Rise up, breathe in. Sink down, breathe out. His fins stopped wiggling. His tummy stopped fluttering."), StoryChapter(title: "The Song", text: "Then Wren began to sing. It was the deepest, softest song in the whole sea. The sound rolled through the water like a warm hug. The seaweed listened. The jellyfish listened. And little Finn tucked himself under Wren's big flipper, and listened too.")], ending: "Finn's eyes closed. The ocean rocked him, gently, gently, like a cradle. \"Goodnight, Finn,\" Wren hummed. Now you can breathe like Wren. Rise up, breathe in. Sink down, breathe out. Your body is heavy and calm, resting in the cool, quiet blue. Goodnight.", lines: []),
        StoryItem(id: "bear", kind: .bedtimeStory, kindLabel: "Bedtime story", title: "Bramble Bear and the Snowy Quiet", color: 0x5A6FB8, chips: ["Audio only", "Choose the length"],
                  summary: "The first snow falls softly on the forest, and Bramble Bear gets cozy in a cool den with a soft cotton blanket.", age: "2+", length: "5–20 min", benefits: ["Cool, quiet imagery for warm, itchy nights", "Counting game to slow down", "Audio only, screen stays dark"], factKey: "sleep",
                  steps: [],
                  chapters: [StoryChapter(title: "The First Snow", text: "In the middle of the forest, Bramble Bear stepped outside and looked up. Something soft and white was drifting down. It landed on his nose. It was cool, and it tickled. \"Snow!\" whispered Bramble. The first snow of winter had come, and the whole forest was going quiet."), StoryChapter(title: "Snowflake Counting", text: "Bramble held out his paw and watched the snowflakes land. One. So gentle. Two. So light. Three. So cool. Four. Each one was different, and each one was perfect. Five. Six. Seven. Bramble yawned a great big bear yawn."), StoryChapter(title: "The Cozy Den", text: "Bramble padded back into his den. It was cool and dark and quiet inside. He smoothed his soft cotton blanket, the one that never felt scratchy, and lay down on his bed of dry leaves. Not too warm. Not too cold. Just right."), StoryChapter(title: "Quiet Sounds", text: "Bramble listened. Outside, the snow fell without a sound. An owl called once, far away. Hoo. The wind sighed through the pine trees. Shhhh. And inside his own chest, Bramble could hear his heart, slow and steady, like a drum played very, very softly.")], ending: "The forest was white and still. Bramble's eyes grew heavy. \"Goodnight, snow,\" he mumbled. \"Goodnight, owl. Goodnight, trees.\" Now you can be still like the forest. Your skin is cool and calm. Your blanket is soft. Your breathing is slow and quiet. Goodnight, little one.", lines: []),
        StoryItem(id: "breathe", kind: .calm, kindLabel: "Calm breathing", title: "Snowflake Breathing", color: 0x5A6FB8, chips: ["Itchy nights", "Calm"],
                  summary: "Breathe in like smelling a flower, out like blowing a snowflake. A short calm-down for big feelings and itchy moments.", age: "3+", length: "3 min", benefits: ["Slows breathing and calms the body", "Gives hands something else to do", "Easy to remember on hard nights"], factKey: "relax",
                  steps: [],
                  chapters: [], ending: "", lines: ["Breathe in slowly, like smelling a flower.", "Breathe out slowly, like blowing a snowflake far away.", "Again. In, and out.", "Your body feels cool and calm."]),
        StoryItem(id: "feelings", kind: .bedtimeStory, kindLabel: "Feelings story", title: "Lumi Has a Grumpy Night", color: 0xB5674B, chips: ["Feelings", "Audio only"],
                  summary: "Lumi feels cross and itchy and doesn't want to sleep. A story about naming big feelings and letting them float away.", age: "3+", length: "5–20 min", benefits: ["Names big feelings out loud", "Shows that feelings pass", "Ends with a calm breath together"], factKey: "quality",
                  steps: [],
                  chapters: [StoryChapter(title: "A Tangled Net", text: "Lumi the Star Catcher was cross. Her star net was tangled. Her skin felt itchy. And she did not want to go to bed, not one bit. She stomped her foot on the cloud, and the cloud went poof."), StoryChapter(title: "Saying It Out Loud", text: "Her friend the moon peeked down. \"You look like you have a big feeling,\" said the moon. Lumi crossed her arms. Then she said it out loud: \"I feel grumpy.\" And something funny happened. Saying it made the grumpy feel a tiny bit smaller."), StoryChapter(title: "Where Feelings Live", text: "\"Where do you feel it?\" asked the moon. Lumi thought. \"In my hands. They feel tight. And in my tummy.\" \"Let's give your hands something kind to do,\" said the moon. Lumi pressed her palms together, then let them go soft. Tight, and soft. Tight, and soft."), StoryChapter(title: "A Feeling Is a Cloud", text: "\"Feelings are like clouds,\" said the moon. \"They come, and they stay a while, and then they float away.\" Lumi watched a cloud drift past. She imagined her grumpy feeling sitting on it, getting smaller and smaller, until it was gone.")], ending: "Lumi untangled her net, one knot at a time. She breathed in slowly, and out slowly. \"I feel calmer,\" she said. \"Me too,\" said the moon. You can do that too. When a big feeling comes, say its name. Breathe in. Breathe out. Watch it float away like a cloud. Goodnight.", lines: []),
        StoryItem(id: "loved", kind: .affirmation, kindLabel: "Affirmation", title: "You Are Loved", color: 0xC46A8E, chips: ["Affirmation", "Calm"],
                  summary: "Warm, simple words that remind your child how deeply they are loved, every day and every night.", age: "3+", length: "4 min", benefits: ["Kind words to fall asleep to", "Simple phrases they can repeat", "Loops softly with the sleep timer"], factKey: "respect",
                  steps: [],
                  chapters: [], ending: "", lines: ["Close your eyes and take a slow breath in. And a slow breath out. Tonight, I want you to listen to something very important, something that is always true.", "You are loved. You are loved when you are happy and when you are grumpy. You are loved on easy days and on itchy days. You are loved when you get it right, and when you make mistakes.", "Love is not something you have to earn. It is already yours. It wraps around you like a soft blanket, and it stays with you all night long, even while you sleep.", "Think of someone who loves you. Picture their face. Feel how warm that feels in your chest. That warm feeling is love, and it is always there for you.", "Say it quietly with me: I am loved. I am loved. I am loved, just as I am."]),
        StoryItem(id: "emotions", kind: .affirmation, kindLabel: "Affirmation", title: "You Are in Charge of Your Emotions", color: 0x6B5BB8, chips: ["Affirmation", "Calm"],
                  summary: "Big feelings are normal. These words help your child notice feelings, name them, and know they can calm their body.", age: "3+", length: "4 min", benefits: ["Kind words to fall asleep to", "Simple phrases they can repeat", "Loops softly with the sleep timer"], factKey: "respect",
                  steps: [],
                  chapters: [], ending: "", lines: ["Let's take a deep breath together. In through your nose, and slowly out through your mouth.", "Everyone has big feelings. Happy feelings, sad feelings, angry feelings, scared feelings. All of them are okay to have. Feelings are not good or bad. They are just feelings.", "Here is something powerful: you are in charge of what you do with your feelings. When a big feeling comes, you can stop, notice it, and give it a name. \"I feel angry.\" \"I feel worried.\" Saying its name makes it smaller.", "Then you can take a slow breath, like blowing out a candle. You can squeeze your hands and let them go soft. You can ask for a hug. You have so many ways to help your body feel calm again.", "Feelings come and go, like waves on the sea. You are the boat, and you can ride the waves.", "Say it with me: I am in charge of my emotions. I can notice my feelings. I can calm my body. I am strong inside."]),
        StoryItem(id: "positive", kind: .affirmation, kindLabel: "Affirmation", title: "You Are a Positive Person", color: 0xD99A3A, chips: ["Affirmation", "Calm"],
                  summary: "Gentle words about finding the good, even on hard days, so your child falls asleep thinking hopeful thoughts.", age: "3+", length: "4 min", benefits: ["Kind words to fall asleep to", "Simple phrases they can repeat", "Loops softly with the sleep timer"], factKey: "respect",
                  steps: [],
                  chapters: [], ending: "", lines: ["Get cozy and let your body sink into your bed. Breathe in slowly. Breathe out slowly.", "Every day has some hard parts and some good parts. Tonight, let's look for the good parts. Maybe you laughed at something silly. Maybe someone gave you a hug. Maybe you tried something new.", "You have a special power. You can look for the good, even when things feel tricky. When a gloomy thought comes along, you can say, \"Hello, thought,\" and then think of something that makes you smile.", "Your mind is like a garden. The thoughts you water are the ones that grow. Tonight, you are watering kind, happy, hopeful thoughts.", "Tomorrow is a brand new day, full of new chances and good surprises.", "Say it with me: I am a positive person. I look for the good. I have happy thoughts. Tomorrow will be a good day."]),
        StoryItem(id: "valuable", kind: .affirmation, kindLabel: "Affirmation", title: "You Are Valuable", color: 0x3F8F8A, chips: ["Affirmation", "Calm"],
                  summary: "Words that help your child know they matter, not for what they do, but for who they are.", age: "3+", length: "4 min", benefits: ["Kind words to fall asleep to", "Simple phrases they can repeat", "Loops softly with the sleep timer"], factKey: "respect",
                  steps: [],
                  chapters: [], ending: "", lines: ["Let your shoulders drop and your hands go soft. Take one big breath in, and let it all the way out.", "There is no one else in the whole world exactly like you. Not your laugh, not your ideas, not the way you see things. You are one of a kind.", "You matter. Not because of what you can do or how you look, but simply because you are you. Your ideas matter. Your feelings matter. Your voice matters.", "Your skin does not decide how special you are. Your heart does, and your heart is full of good things: kindness, curiosity, and courage.", "The people around you are lucky to have you. The world is better because you are in it.", "Say it with me: I am valuable. I matter. There is only one me, and I am wonderful."]),
        StoryItem(id: "brave", kind: .affirmation, kindLabel: "Affirmation", title: "You Are Brave in Your Skin", color: 0xB9637A, chips: ["Affirmation", "Calm"],
                  summary: "Positive words about skin that is healing, bravery on itchy days, and being more than your skin.", age: "3+", length: "4 min", benefits: ["Kind words to fall asleep to", "Simple phrases they can repeat", "Loops softly with the sleep timer"], factKey: "respect",
                  steps: [],
                  chapters: [], ending: "", lines: ["Close your eyes and take a slow, cool breath. Feel your body resting, heavy and calm.", "Some days your skin feels itchy or sore, and that can be really hard. Being uncomfortable and still trying your best is what bravery looks like. And you do it every day.", "Every night, your skin is working hard to heal. While you sleep, it is getting stronger and calmer, a little bit at a time.", "Your skin is just one part of you. You are also funny, and kind, and clever, and creative. You are so much more than your skin.", "When the itch comes, you know what to do. Breathe slowly. Press gently instead of scratching. Ask for help. You are learning, and you are doing great.", "Say it with me: I am brave in my skin. My skin is healing. I am more than my skin. I am safe, and I am loved."]),
        StoryItem(id: "calm", kind: .affirmation, kindLabel: "Affirmation", title: "You Are Calm", color: 0x4F7FB8, chips: ["Affirmation", "Calm"],
                  summary: "A slow, quiet affirmation that pairs calm words with calm breathing.", age: "3+", length: "4 min", benefits: ["Kind words to fall asleep to", "Simple phrases they can repeat", "Loops softly with the sleep timer"], factKey: "respect",
                  steps: [],
                  chapters: [], ending: "", lines: ["Let's breathe together. Breathe in, and feel your tummy rise like a balloon. Breathe out, and feel it float back down.", "Your body knows how to be calm. Your feet are calm. Your legs are calm. Your hands are soft and still. Your face is relaxed.", "Imagine a quiet lake at night, smooth as glass, with the moon shining on top. That lake is inside you. Whenever you need it, you can find that quiet place.", "Noises can come and go, thoughts can come and go, and you can stay calm and still, like the lake.", "Say it slowly with me: I am calm. I am peaceful. I am ready to rest."]),
        StoryItem(id: "kind", kind: .affirmation, kindLabel: "Affirmation", title: "You Are Kind", color: 0x7BAF6A, chips: ["Affirmation", "Calm"],
                  summary: "Words that celebrate kindness to others, and to yourself.", age: "3+", length: "4 min", benefits: ["Kind words to fall asleep to", "Simple phrases they can repeat", "Loops softly with the sleep timer"], factKey: "respect",
                  steps: [],
                  chapters: [], ending: "", lines: ["Snuggle in and take a soft breath in, and a soft breath out.", "Kindness is a kind of magic. A smile, a gentle word, sharing, helping. Each small kind thing makes the world a little brighter.", "You have a kind heart. You notice when someone is sad. You know how good it feels to help.", "And here is something just as important: you can be kind to yourself too. When you make a mistake, you can say, \"That's okay. I'm still learning.\" You can be gentle with your own body, and your own feelings.", "Say it with me: I am kind to others. I am kind to myself. My kindness makes the world brighter."]),
        StoryItem(id: "enough", kind: .affirmation, kindLabel: "Affirmation", title: "You Are Enough", color: 0x8C6BC4, chips: ["Affirmation", "Calm"],
                  summary: "A gentle reminder that your child does not have to be perfect to be wonderful.", age: "3+", length: "4 min", benefits: ["Kind words to fall asleep to", "Simple phrases they can repeat", "Loops softly with the sleep timer"], factKey: "respect",
                  steps: [],
                  chapters: [], ending: "", lines: ["Rest your head and let your whole body go soft. Breathe in. Breathe out.", "You do not have to be perfect. Nobody is. Not grown-ups, not kids, not anybody.", "You are enough, right now, just as you are. On days you feel strong and on days you feel tired. On days your skin feels good and on days it doesn't.", "You did your best today, and your best is enough. Tomorrow you can try again, and that will be enough too.", "Say it with me: I am enough. I am enough. I am enough, just as I am."]),
    ]

    static let facts: [String: StoryFact] = [
        "eczema": StoryFact(text: "Children massaged for 20 minutes each night with their moisturizer had less eczema than children who got moisturizer alone.", source: "Schachner, Field et al., Pediatric Dermatology, 1998"),
        "relax": StoryFact(text: "Across studies, massage lowered cortisol, a stress hormone, by about 31% on average.", source: "Field et al., International Journal of Neuroscience, 2005"),
        "sleep": StoryFact(text: "In a randomized trial, a 15-minute bedtime massage helped babies fall asleep faster and wake less, and their mothers slept longer.", source: "Rezaei et al., 2023"),
        "parent": StoryFact(text: "Mothers who massaged their babies with eczema had lower anxiety and depression scores.", source: "Lin et al., Frontiers in Public Health, 2023"),
        "quality": StoryFact(text: "A massage is quality time: ten minutes of undivided attention, skin to skin, at the end of the day.", source: "Why bedtime touch matters"),
        "respect": StoryFact(text: "Asking \"Can I?\" before touch teaches children their body belongs to them, and builds trust.", source: "A core principle of body-safety teaching"),
        "tummy": StoryFact(text: "Gentle clockwise tummy strokes are a traditional way to soothe tummy discomfort. Research in babies is mixed, so think of it as comfort, not a cure.", source: "Honest note"),
        "protocol": StoryFact(text: "Every stroke follows the moderate-pressure routine used in massage research: long strokes and circles on the back, arms, hands, legs, feet, chest and tummy. Moderate pressure relaxes; very light touch can tickle.", source: "Schachner, Field et al., 1998; Field, Int J Neurosci, 2010"),
        "infantSleep": StoryFact(text: "Babies and toddlers massaged for 15 minutes before bed for a month fell asleep more easily and had fewer sleep problems.", source: "Field & Hernandez-Reif, Early Child Development and Care, 2001"),
        "reflex": StoryFact(text: "Reflexology is a traditional, gentle foot massage. Research on its health effects is limited, but slow foot rubs are an easy, calming way to wind down together.", source: "Honest note"),
        "noise": StoryFact(text: "In a small classic study, 80% of newborns fell asleep within 5 minutes with steady white noise, compared with 25% without.", source: "Spencer et al., Archives of Disease in Childhood, 1990"),
    ]
